<?php echo '<div class="card table-wrap"><div class="card-head"><h3>Beginning Balance Update History</h3></div><table class="table"><tr><th>Date</th><th>Source</th><th>Rows</th><th>Status</th><th>Updated By</th><th></th></tr>';foreach($pdo->query(history_sql("SELECT b.*,u.name user_name FROM import_batches b LEFT JOIN users u ON u.id=b.user_id WHERE import_type='Beginning Balance' ORDER BY b.id DESC LIMIT 500")) as $r)echo '<tr><td>'.e($r['created_at']).'</td><td>'.e($r['filename']).'</td><td>'.(int)$r['rows_read'].'</td><td>'.badge(beginning_status_label($r['status']),status_badge_class($r['status'])).'</td><td>'.e($r['user_name']).'</td><td><a class="btn ghost sm" href="?page=import_detail&id='.(int)$r['id'].'">View Details</a></td></tr>';echo '</table></div>';
